class Solution:
    def isPossibleToSplit(self, nums: List[int]) -> bool:
        # Count frequency of each number
        freq = {}
        for num in nums:
            if num in freq:
                freq[num] += 1
            else:
                freq[num] = 1

        num_distinct = len(freq.keys())

        # We need to divide into equal halves
        needed_distinct = len(nums) // 2

        # Check if there are enough distinct elements
        if num_distinct >= needed_distinct:
            count = 0
            # Count of elements that appear at least twice
            for v in freq.values():
                if v > 1:
                    count += 1
                if count + num_distinct >= needed_distinct:
                    return True
        return False
```

